    selectableRentalSpaces() { const expectedType = this.isSharedRental ? 'room' : 'whole_unit'; return this.rentalSpaces.filter(space => space.status === 'active' && space.spaceType === expectedType); },
    selectedRentalSpace() { return this.selectableRentalSpaces.find(space => String(space.id) === String(this.selectedRentalSpaceId)) || null; },
    occupiedRentalSpaceCount() { return this.selectableRentalSpaces.filter(space => space.currentLeaseId).length; },
    scopedWorkspace() {
