      operationsChargeTotalAmount() { return this.operationsConfirmedCharges.reduce((total, item) => total + Number(item.amount || 0), 0); },
      operationsRentTotal() { return this.formatOperationsAmount(Math.max(0, Number(this.operationsInvoice?.amountDue || 0) - this.operationsChargeTotalAmount)); },
     operationsWorkOrders() { return this.operationsWorkspace?.workOrders || []; },
      operationsSharedRoomLeases() { return (this.operationsWorkspace?.activeLeases || []).filter(item => item.rentalSpaceType === 'room'); },
      operationsCanSplitSharedCharge() { return this.operationsSharedRoomLeases.length >= 2; },
      operationsCurrentLeaseId() { return this.rentalWorkbench.currentLease?.id || this.rentalWorkbench.currentLease?.leaseId || null; },
      operationsCurrentTenantId() { return this.rentalWorkbench.currentLease?.tenantId || this.currentTenant?.id || null; },
      operationsWorkOrderReserveShortage() { const formAmount = Number(this.operationsWorkOrderHandlingForm.actualAmount || 0); const reserveAvailable = Number(this.operationsWorkOrderHandling?.reserveBalance || 0) - Number(this.operationsWorkOrderHandling?.reserveDeductedAmount || 0); return Math.max(0, formAmount - reserveAvailable); },
      operationsRenewalMinDate() { const latest = this.operationsRenewalPeriods.at(-1); const leaseEnd = latest?.endDate || this.operationsWorkspace?.lease?.endDate || this.rentalWorkbench.currentLease?.endDate; return leaseEnd ? dateAfter(leaseEnd, 1) : this.todayDate(); },
      operationsManagementTotal() { return this.formatOperationsAmount(this.operationsConfirmedCharges.filter(item => item.chargeType === 'management').reduce((total, item) => total + Number(item.amount || 0), 0)); },
      operationsUtilitiesTotal() { return this.formatOperationsAmount(this.operationsConfirmedCharges.filter(item => item.chargeType === 'utilities').reduce((total, item) => total + Number(item.amount || 0), 0)); },
      operationsOtherTotal() { return this.formatOperationsAmount(this.operationsConfirmedCharges.filter(item => ['maintenance', 'other'].includes(item.chargeType)).reduce((total, item) => total + Number(item.amount || 0), 0)); },
      operationsSelectedExpenseUnit() { const unitId = this.operationsPhysicalUnitId(); return (this.operationsOptions.units || []).find(item => Number(item.unitId) === unitId) || null; },
      operationsExpenseTotal() { return this.operationsExpenses.reduce((total, item) => total + Number(item.amount || 0), 0); },
      operationsPendingExpenseCount() { return this.operationsExpenseReviews.length; },
      operationsActiveMaintenanceCount() { return this.operationsWorkOrders.filter(item => !['completed', 'cancelled'].includes(item.status)).length; },
      operationsFormTitle() { const reviewConfirm = this.operationsSelectedReview?.recordType === 'tenant_charge' ? this.$t('processCenter.operationsChargeConfirm') : this.$t('processCenter.operationsExpenseConfirm'); return ({ charge: this.$t('processCenter.operationsFormChargeTitle'), workOrder: this.$t('processCenter.operationsFormWorkOrderTitle'), invoice: this.$t('processCenter.operationsFormInvoiceTitle'), receipt: this.$t('processCenter.operationsFormReceiptTitle'), expense: this.$t('processCenter.operationsCreateExpense'), expenseReview: this.operationsReviewDecision === 'confirm' ? reviewConfirm : this.$t('processCenter.operationsExpenseReject') })[this.operationsFormType] || ''; },
      operationsFormHint() { return ({ charge: this.$t('processCenter.operationsFormChargeHint'), workOrder: this.$t('processCenter.operationsFormWorkOrderHint'), invoice: this.$t('processCenter.operationsFormInvoiceHint'), receipt: this.$t('processCenter.operationsFormReceiptHint'), expense: this.$t('processCenter.operationsExpenseHint'), expenseReview: this.$t('processCenter.operationsExpenseReviewHint') })[this.operationsFormType] || ''; },
      operationsFormSubmitLabel() { if (this.operationsFormType === 'expenseReview') return this.operationsReviewDecision === 'confirm' ? this.operationsReviewConfirmLabel(this.operationsSelectedReview) : this.$t('processCenter.operationsExpenseReject'); return this.operationsFormType === 'expense' ? (this.operationsEditingExpenseId ? this.$t('projectManagement.edit') : this.$t('processCenter.operationsCreateExpense')) : this.$t('processCenter.operationsFormSave'); },
      handoverCategoryOptions() { return HANDOVER_CATEGORIES.map((value, index) => ({ value, label: this.$t(`legacy.${HANDOVER_CATEGORY_LABEL_KEYS[index]}`) })); },
      handoverPhotoSectionOptions() { return HANDOVER_PHOTO_SECTIONS.map(section => ({ ...section, label: this.$t(`processCenter.handoverPhotoSections.${section.labelKey}`) })); },
    journeySteps() {
      if (!this.selectedProperty) return [];
      const titled = this.rentalWorkbench.stages.map(item => ({ ...item, title: item.key === 'propertySetup' ? this.$t('processCenter.journeyPropertySetup') : this.stageTitle(item) }));
      const byKey = Object.fromEntries(titled.map(item => [item.key, item]));
      const leasing = byKey.leasingSigning;
      const operations = byKey.rentalOperations;
      const mandateReady = byKey.mandateAuthorization?.status === 'completed';
      const tenantReady = Boolean(this.currentTenant?.id || this.rentalWorkbench.currentLease?.tenantId || this.rentalWorkbench.currentLease?.tenantName);
      const leaseReady = Boolean(this.rentalWorkbench.currentLease);
      const tenantSetup = {
        ...leasing,
        key: 'tenantSetup',
        title: this.$t('processCenter.journeyTenantSetup'),
        sourceStageKey: 'leasingSigning',
        status: !mandateReady ? 'pending' : tenantReady ? 'completed' : 'in_progress',
        missingItems: !mandateReady ? ['mandate_activation'] : tenantReady ? [] : ['tenant'],
        primaryAction: !tenantReady && leasing?.primaryAction?.key === 'create_tenant' ? leasing.primaryAction : null,
      };
      const leaseSetup = {
        ...leasing,
        key: 'leaseSetup',
        title: this.$t('processCenter.journeyLeaseSetup'),
        sourceStageKey: 'leasingSigning',
        status: !tenantReady ? 'pending' : leaseReady ? 'completed' : 'in_progress',
        missingItems: !tenantReady ? ['tenant'] : leaseReady ? [] : ['lease'],
        primaryAction: tenantReady && !leaseReady && leasing?.primaryAction?.key === 'create_lease' ? leasing.primaryAction : null,
      };
      return [
        byKey.propertySetup,
        byKey.mandateAuthorization,
        tenantSetup,
        leaseSetup,
        byKey.moveInCollection,
        { ...operations, key: 'billingOperations', title: this.$t('processCenter.journeyBilling'), sourceStageKey: 'rentalOperations', operationsTab: 'billing', primaryAction: null },
        { ...operations, key: 'maintenanceOperations', title: this.$t('processCenter.journeyMaintenance'), sourceStageKey: 'rentalOperations', operationsTab: 'maintenance', primaryAction: null },
        byKey.leaseClosure,
      ].filter(Boolean);
    },
    journeyCompletedCount() { return this.journeySteps.filter(step => step.status === 'completed').length; },
    journeyCurrentStep() { return this.journeySteps.find(step => step.status !== 'completed') || null; },
    selectedJourneyStep() { return this.journeySteps.find(step => step.key === this.selectedJourneyKey) || this.journeyCurrentStep || this.journeySteps[this.journeySteps.length - 1] || null; },
    selectedSystemStage() { return this.selectedJourneyStep || null; },
    actionPanelTitle() { return this.activeAction ? this.$t('processCenter.actions.' + this.activeAction) : ''; },
    actionPanelHint() { return this.$t('processCenter.actionPanelHint'); },
    actionSubmitLabel() { return this.activeAction === 'complete_move_in_handover' ? this.$t('processCenter.actions.complete_move_in_handover') : ['complete_handover', 'complete_property_data'].includes(this.activeAction) ? this.$t('processCenter.actionFields.savePreparation') : this.activeAction === 'create_tenant' && this.actionForm.existingTenantId ? this.$t('processCenter.actions.use_existing_tenant') : this.activeAction === 'create_first_invoice' ? this.$t('processCenter.actions.create_first_invoice') : this.$t('processCenter.actionFields.save'); },
  },
  watch: {
    'actionForm.monthlyRent'(value) { if (this.activeAction === 'create_lease') this.actionForm.depositAmount = calculateTenantDeposit(value); },
    operationsMonth() { if (this.operationsCenterOpen) Promise.all([this.loadOperationsWorkspace(), this.loadOperationsExpenses(), this.loadOperationsExpenseReviews()]); },
    operationsTab() { this.operationsFormType = ''; },
    operationsFormType(value) { if (value) this.revealOperationsForm(); },
  },
  mounted() { this.loadProperties(); window.addEventListener('focus', this.refreshProcessState); },
  beforeUnmount() { window.removeEventListener('focus', this.refreshProcessState); clearTimeout(this.setupProjectCodeTimer); },
  methods: {
    calculateTenantDeposit,
    selectJourneyStep(step) { if (!step || this.actionBusy) return; if (this.activeAction) this.closeAction(); this.selectedJourneyKey = step.key; },
    selectRentalSpace(space) {
      if (!space || String(space.id) === String(this.selectedRentalSpaceId)) return;
      if (this.activeAction) this.closeAction();
      this.selectedRentalSpaceId = Number(space.id);
      this.currentTenant = null;
      this.selectedJourneyKey = '';
    },
    syncRentalSpaceSelection(spaces = []) {
      this.rentalSpaces = Array.isArray(spaces) ? spaces : [];
      const expectedType = this.isSharedRental ? 'room' : 'whole_unit';
      const selectable = this.rentalSpaces.filter(space => space.status === 'active' && space.spaceType === expectedType);
      const preserved = selectable.find(space => String(space.id) === String(this.selectedRentalSpaceId));
      const preferred = preserved || selectable.find(space => space.currentLeaseId) || selectable[0] || null;
      this.selectedRentalSpaceId = preferred ? Number(preferred.id) : null;
    },
    journeyStepNumber(step) { const index = this.journeySteps.findIndex(item => item.key === step?.key); return index >= 0 ? index + 1 : '—'; },
    journeyStepDescription(step) {
      const descriptions = {
        propertySetup: 'journeyDescriptionPropertySetup',
        mandateAuthorization: 'journeyDescriptionMandate',
        tenantSetup: 'journeyDescriptionTenant',
        leaseSetup: 'journeyDescriptionLease',
        moveInCollection: 'journeyDescriptionMoveIn',
        billingOperations: 'journeyDescriptionBilling',
        maintenanceOperations: 'journeyDescriptionMaintenance',
        leaseClosure: 'journeyDescriptionClosure',
      };
      return descriptions[step?.key] ? this.$t(`processCenter.${descriptions[step.key]}`) : '';
    },
    handoverCategoryLabel(value) { return this.handoverCategoryOptions.find(item => item.value === value)?.label || value || this.$t('processCenter.actionFields.checklistCategory'); },
    isRentalControlEligible(property) { return String(property?.assetStage || '').toUpperCase() === 'OPERATING' && String(property?.rentalListingStatus || 'listed').toLowerCase() !== 'off_market'; },
    openRentalOffMarket() { this.rentalOffMarketError = ''; this.rentalOffMarketForm = { reasonCode: 'OWNER_REQUEST', note: '' }; this.rentalOffMarketOpen = true; },
    closeRentalOffMarket() { if (this.rentalOffMarketSaving) return; this.rentalOffMarketOpen = false; this.rentalOffMarketError = ''; },
    async confirmRentalOffMarket() { if (this.rentalOffMarketSaving || !this.selectedProperty) return; this.rentalOffMarketSaving = true; this.rentalOffMarketError = ''; try { const unitId = Number(this.selectedProperty.unitId || this.selectedProperty.id); await markAdminPropertyOffMarket(unitId, { reasonCode: this.rentalOffMarketForm.reasonCode, note: this.rentalOffMarketForm.note || null }); this.rentalOffMarketOpen = false; this.page?.showToast?.(this.$t('processCenter.offMarketSuccess')); await this.loadProperties(); } catch (error) { this.rentalOffMarketError = error.message || this.$t('processCenter.offMarketFailed'); } finally { this.rentalOffMarketSaving = false; } },
    async openSetupWizard() {
      this.setupWizardOpen = true;
      this.setupStep = 1;
      this.setupError = '';
      this.setupBusy = true;
      this.setupProjectMode = 'existing';
      this.setupOwnerMode = 'existing';
      this.setupProjectId = '';
      this.setupOwnerId = '';
      this.setupProjectCodeStatus = 'idle';
      this.setupProjectCodeRequest += 1;
      clearTimeout(this.setupProjectCodeTimer);
      this.setupProjectForm = { projectCode: '', name: '', state: '', city: '', address: '', countryCode: 'MY', status: 'active' };
      this.setupOwnerForm = { fullName: '', mobilePhone: '', mobileCountry: 'MY', mobileNational: '', phone: '', email: '', identityNo: '', passportNo: '', status: 'active' };
      this.setupOwnerPhoneError = '';
      this.setupPropertyForm = { building: '', floorNo: '', unitNo: '', unitType: '', areaSqm: null, bedroomCount: 0, listingStatus: 'available', assetStage: 'OPERATING', actualHandoverDate: '', services: ['RENTAL'], purchasePrice: 0, ownershipPercent: 100, primary: true, startDate: new Date().toISOString().slice(0, 10) };
      try {
        const [projectResponse, owners] = await Promise.all([fetchAdminProjects({ page: 1, pageSize: 500, status: 'active' }), fetchAdminOwners()]);
        this.setupProjects = projectResponse?.rows || [];
        this.setupOwners = (owners || []).filter(owner => owner.status === 'active');
        if (!this.setupProjects.length) this.setupProjectMode = 'new';
        if (!this.setupOwners.length) this.setupOwnerMode = 'new';
      } catch (error) {
        this.setupError = error.message || this.$t('processCenter.setupLoadFailed');
      } finally {
        this.setupBusy = false;
      }
    },
    closeSetupWizard() { if (!this.setupBusy) { clearTimeout(this.setupProjectCodeTimer); this.setupProjectCodeRequest += 1; this.setupWizardOpen = false; } },
    selectSetupProjectMode(mode) { this.setupProjectMode = mode; this.setupError = ''; this.setupProjectCodeStatus = 'idle'; this.setupProjectCodeRequest += 1; clearTimeout(this.setupProjectCodeTimer); },
    scheduleSetupProjectCodeCheck() {
      clearTimeout(this.setupProjectCodeTimer);
      this.setupProjectCodeRequest += 1;
      if (!this.setupProjectForm.projectCode.trim()) { this.setupProjectCodeStatus = 'idle'; return; }
      this.setupProjectCodeStatus = 'checking';
      this.setupProjectCodeTimer = window.setTimeout(() => this.checkSetupProjectCode(), 350);
    },
    async checkSetupProjectCode() {
      clearTimeout(this.setupProjectCodeTimer);
      const code = this.setupProjectForm.projectCode.trim().toUpperCase();
      if (!code) { this.setupProjectCodeStatus = 'idle'; return false; }
      const requestId = ++this.setupProjectCodeRequest;
      this.setupProjectCodeStatus = 'checking';
      try {
        const response = await checkAdminProjectCodeAvailability(code);
        if (requestId !== this.setupProjectCodeRequest) return false;
        const available = response?.available === true;
        this.setupProjectCodeStatus = available ? 'available' : 'duplicate';
        this.setupError = available ? '' : this.$t('processCenter.projectCodeExists');
        return available;
      } catch (error) {
        if (requestId !== this.setupProjectCodeRequest) return false;
        this.setupProjectCodeStatus = 'error';
        this.setupError = error.message || this.$t('processCenter.projectCodeCheckFailed');
        return false;
      }
    },
    async nextSetupStep() {
      this.setupError = '';
      if (this.setupStep === 1) {
        if (this.setupProjectMode === 'existing' && !this.setupProjectId) return void (this.setupError = this.$t('processCenter.selectExistingProject'));
        if (this.setupProjectMode === 'new' && (!this.setupProjectForm.projectCode || !this.setupProjectForm.name)) return void (this.setupError = this.$t('processCenter.projectRequired'));
        if (this.setupProjectMode === 'new') { const available = await this.checkSetupProjectCode(); if (!available) return; }
      }
      if (this.setupStep === 2) {
        if (this.setupOwnerMode === 'existing' && !this.setupOwnerId) return void (this.setupError = this.$t('processCenter.selectExistingOwner'));
        if (this.setupOwnerMode === 'new' && !this.setupOwnerForm.fullName) return void (this.setupError = this.$t('processCenter.ownerRequired'));
        if (this.setupOwnerMode === 'new') { const mobile = this.validateSetupOwnerPhone(true); if (!mobile.valid) return; this.setupOwnerForm.mobilePhone = mobile.e164; this.setupOwnerForm.phone = mobile.e164; }
      }
      this.setupStep += 1;
    },
    async submitSetupWizard() {
      if (!this.setupPropertyForm.unitNo) { this.setupError = this.$t('processCenter.unitRequired'); return; }
      if (!this.setupPropertyForm.actualHandoverDate) { this.setupError = this.$t('processCenter.handoverDateRequired'); return; }
      this.setupBusy = true;
      this.setupError = '';
      try {
        let projectId = Number(this.setupProjectId);
